// V2: Go-backed admission precedes every native resource and API.
app.use((req, res, next) => {
    const gate = globalThis[Symbol.for('virtual-companion.bridge')]?.hostAuth;
    if (!gate) return res.status(503).json({ code: 'VC_AUTH_UNAVAILABLE', message: 'Authentication unavailable' });
    return gate(req, res, next);
});
app.use( setUserDataMiddleware);

// W06: temporary uploads belong to the authenticated user's deletion scope.
const vcNativeUpload = multer({ storage: multer.diskStorage({
    destination(req, _file, done) {
        const root = req.user?.directories?.root;
        if (!root) return done(new Error('Authenticated upload directory required'), '');
        const target = path.join(root, '.uploads');
        try { fs.mkdirSync(target, { recursive: true, mode: 0o700 }); done(null, target); }
        catch (error) { done(error, ''); }
    },
}), limits: { fieldSize: 500 * 1024 * 1024 } }).single('avatar');
app.use((req, res, next) => {
    // VO-7: this exact route streams bounded WAV in memory; native multer writes uploads to disk.
    if (req.method === 'POST' && req.path === '/api/plugins/virtual-companion/go/api/v1/voice/asr') return next();
    return vcNativeUpload(req, res, next);
});
